Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='effectsframe', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Place every feature in one frame: pure store, proposing agent, inputs, outputs', body='The pure store holds the prodromes and the readings that fold over them. The agent reads the store and proposes, and never performs an effect. Inputs are sources behind one port. Outputs are sinks behind one port, each a content-addressed object performed at most once and confirmed by its input, not by the sink reply.', rationale='One frame keeps each new feature from adding its own mechanism.', supersedes=()))